edm.jsonImport = function (file) {
    if (!window._assetCache) {
        window._assetCache = {};
    }

    if (window._assetCache[file]) {
        return window._assetCache[file];
    }
    var asset = ndbx.findAsset(file);
    if (typeof asset === 'undefined') {
        return;
    }
    var result = JSON.parse(asset);
    window._assetCache[file] = result;
    return result;
};

edm.leftRect = function (x, y, w, h) {
    var p = new g.Path();
    p.addRect(x, y, w, h);
    return p;
};

edm.dbToIntensity = function (db, scale) {
    db /= 10;
    var v = Math.pow(10, db);
    return v * scale;
};

edm.autoLink = function (shapes, orientation) {
    var p = new g.Path();
    if (shapes.length < 2) {
        return p;
    }
    var results = [];
    for (var i = 1; i < shapes.length; i++) {
        p.extend(g.link(shapes[i - 1], shapes[i], orientation));

    }
    return p;

};

edm.smoothConnect = function (points) {
    var p = new g.Path();
    if (points.length === 0) {
        return p;
    }
    var prevPt = points[0]
    p.moveTo(prevPt.x, prevPt.y);
    for (var i = 1; i < points.length; i++) {
        var pt = points[i];
        var hw = (pt.x - prevPt.x) * 0.5;
        p.curveTo(prevPt.x + hw, prevPt.y, pt.x - hw, pt.y, pt.x, pt.y);
        prevPt = pt;
    }
    p.fill = null;
    p.stroke = 'black';
    return p;
};

edm.addPoint = function (pt1, pt2) {

    return new g.Point((pt1.x/2+pt2.x/2),pt1.y+pt2.y);
};
